 function searchPages(terms,query){const qt=tokens(query);if(!qt.length)return [];const n=normalize(query),syn=groups.filter(g=>g.some(w=>n.includes(w))),scores=new Map();for(const [term,pages] of Object.entries(terms)){const direct=qt.some(q=>near(q,term)||(q.length>=5&&term.startsWith(q))),related=syn.some(g=>g.some(q=>q.length>=4&&term.startsWith(q)));if(direct||related)for(const page of pages)scores.set(page,(scores.get(page)||0)+(direct?4:1));}return [...scores].filter(([page,score])=>score>=4).map(([page,score])=>({page,score})).sort((a,b)=>b.score-a.score||a.page-b.page);}
 function candidateFilter(rows,{query='',province='',chamber='',includeSubstitutes=false,heads=false}={}){const q=normalize(query);return rows.filter(c=>(!province||c.province===province)&&(!chamber||c.chamber===chamber)&&(includeSubstitutes||c.kind!=='suplente')&&(!heads||(c.order===1&&c.kind!=='suplente'&&(!c.chamber||c.chamber==='Congreso')))&&normalize(c.name+' '+c.party+' '+(c.district||'')).includes(q));}
