 function selections(available,previous,count=3){const used=new Set(),result=Array.from({length:count},(_,i)=>{const value=previous[i];if(value&&available.includes(value)&&!used.has(value)){used.add(value);return value;}return '';});return result.map((value,i)=>{if(value||(i===2&&previous[i]===''))return value;const next=available.find(x=>!used.has(x))||'';if(next)used.add(next);return next;});}
 function eventDate(e){const value=String(e.date||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return null;const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value?value:null;}
