 function diffText(before,after){const a=String(before||'').trim().split(/\s+/).filter(Boolean),b=String(after||'').trim().split(/\s+/).filter(Boolean);let prefix=0,suffix=0;while(prefix<a.length&&prefix<b.length&&a[prefix]===b[prefix])prefix++;while(suffix<a.length-prefix&&suffix<b.length-prefix&&a[a.length-1-suffix]===b[b.length-1-suffix])suffix++;const render=(words,tag)=>{const middle=words.slice(prefix,words.length-suffix),start=words.slice(0,prefix),end=suffix?words.slice(-suffix):[];return [escape(start.join(' ')),middle.length?'<'+tag+'>'+escape(middle.join(' '))+'</'+tag+'>':'',escape(end.join(' '))].filter(Boolean).join(' ');};return {before:render(a,'del'),after:render(b,'ins')};}
